15	  steps: Step[];
16	};
17	
18	export type QuoteResult = {
19	  premium: number;
20	};
21	
22	export type ScenarioResults = {
23	  results: QuoteResult[];
24	};
25	
26	const PROCESSING_FEE = 5;
27	
28	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
38	
39	const percentOf = (amount: number, percent: number): number =>
40	  (amount * percent) / 100;
41	
42	const addPercent = (amount: number, percent: number): number =>
43	  amount + percentOf(amount, percent);
44	
45	const itemBasePremium = (item: Item): number =>
46	  BASE_PREMIUM_BY_TYPE[item.type];
47	
48	const BLOCK_SIZE = 3;
49	
50	const BLOCK_PREMIUM = 60;
51	
52	const sumOf = (amounts: number[]): number =>
53	  amounts.reduce((sum, amount) => sum + amount, 0);
54	
55	const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
56	
57	const sumOfItemBasePremiums = (items: Item[]): number =>
58	  sumOf(items.map(itemBasePremium));
59	
60	const groupByType = (items: Item[]): Item[][] => {
61	  const types = new Set(items.map((item) => item.type));
62	
63	  return [...types].map((type) => items.filter((item) => item.type === type));
64	};
65	
66	const itemGroupBasePremium = (items: Item[]): number =>
67	  formsABlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);
68	
69	const policyBasePremium = (items: Item[]): number =>
70	  sumOf(groupByType(items).map(itemGroupBasePremium));
71	
72	const roundPremiumInMHPCOsFavor = (amount: number): number =>
73	  Math.ceil(amount);
74	
75	// Every test so far quotes a new customer's first contract, so this is the only
76	// policy-wide modifier the tests demand. Loyalty and follow-up land here later.
77	const applyPolicyModifiers = (basePremium: number): number =>
78	  addPercent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
79	
80	const CURSE_SURCHARGE_PERCENT = 50;
81	
82	const HIGH_ENCHANTMENT_LEVEL = 5;
83	
84	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
85	
86	const isHighlyEnchanted = (item: Item): boolean =>
87	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
88	
89	// Item-scoped surcharges are charged on the item's own base premium, so they
90	// must NOT go through applyPolicyModifiers.
91	const itemSurcharges = (item: Item): number => {
92	  const basePremium = itemBasePremium(item);
93	  const surchargeIf = (applies: boolean, percent: number): number =>
94	    applies ? percentOf(basePremium, percent) : 0;
95	
96	  return (
97	    surchargeIf(item.cursed === true, CURSE_SURCHARGE_PERCENT) +
98	    surchargeIf(isHighlyEnchanted(item), HIGH_ENCHANTMENT_SURCHARGE_PERCENT)
99	  );
100	};
101	
102	const policyItemSurcharges = (items: Item[]): number =>
103	  sumOf(items.map(itemSurcharges));
104	
105	const quotePremium = (items: Item[]): number =>
106	  roundPremiumInMHPCOsFavor(
107	    applyPolicyModifiers(policyBasePremium(items)) +
108	      policyItemSurcharges(items) +
109	      PROCESSING_FEE,
110	  );
111	
112	export const runScenario = (scenario: Scenario): ScenarioResults => ({
113	  results: scenario.steps.map((step) => ({
114	    premium: quotePremium(step.items ?? []),
115	  })),
116	});
